1505	export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
1506	  const ctx = await ownedSiteAccount(accountId);
1507	  if ("error" in ctx) return { error: ctx.error };
1508	  const { a } = ctx;
1509	  const clean = String(label ?? "").trim().toLowerCase();
1510	  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
1511	  const fqdn = `${clean}.${a.primaryDomain}`;
1512	  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
1513	  // Reject if another tenant already claimed this exact hostname as an addon domain
1514	  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
1515	  // path (audit HIGH-1, reverse direction).
1516	  if (await isHostnameClaimed(fqdn)) {
1517	    return { error: "That hostname is already in use on Nxeon." };
1518	  }
1519	  const { docroot } = subdomainPaths(a.username, clean);
1520	  try {
1521	    await db.$transaction(async (tx) => {
1522	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1523	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1524	      if (subs + addons >= a.maxSites) throw new Error("CAP");
1525	      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
1526	      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) — not the
1527	      // advisory isHostnameClaimed read above — is what actually stops a co-tenant
1528	      // from committing this same server_name as their primary/subdomain/addon.
1529	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(fqdn), accountId: a.id, kind: "SUBDOMAIN" } });
1530	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
1531	    }, { isolationLevel: "Serializable" });
1532	  } catch (e) {
1533	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
1534	    if (isUniqueViolation(e)) return { error: "That hostname is already in use on Nxeon." };
1535	    return { error: "That subdomain already exists, or the request raced — try again." };
1536	  }
1537	  revalidatePath(`/dashboard/hosting/${accountId}`);
1538	  return { ok: true };
1539	}
