  nodes: {
    id: string; name: string; publicIp: string; status: string; enabled: boolean; used: number; maxAccounts: number;
    hardenStatus: string; hardenedAt: string | null; hardenLog: string | null;
    // Per-node capacity utilization (accounts + disk) computed against the admin
    // WARN/CRITICAL thresholds. Powers the meters + severity badge in HostingInfra.
    util: {
      severity: "OK" | "WARN" | "CRITICAL";
      warnPct: number;
      critPct: number;
      dims: { dimension: string; pct: number; sev: "OK" | "WARN" | "CRITICAL"; detail: string }[];
    };
  }[];
}> {
  await requireArea("fleet");
  const t = await nodeThresholds();
  const [nodes, util] = await Promise.all([
    db.hostingNode.findMany({ orderBy: { name: "asc" } }),
    hostingNodeUtil(t),
  ]);
  const utilById = new Map(util.map((u) => [u.id, u]));
  const nodeViews = await Promise.all(
    nodes.map(async (n) => {
      const u = utilById.get(n.id);
      return {
        id: n.id, name: n.name, publicIp: n.publicIp, status: n.status, enabled: n.enabled,
        maxAccounts: n.maxAccounts,
        hardenStatus: n.hardenStatus, hardenedAt: n.hardenedAt?.toISOString() ?? null, hardenLog: n.hardenLog,
        used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
        util: {
          severity: u?.severity ?? ("OK" as const),
          warnPct: t.warnPct,
          critPct: t.critPct,
          dims: (u?.dims ?? []).map((d) => ({
            dimension: d.dimension,
            pct: Math.round(d.pct),
            sev: severityFor(d.pct, t),
            detail: d.detail,
          })),
        },
      };
    }),
  );
  return { nodes: nodeViews };
}

