    data: { name, publicIp, sshHost, sshPort, rootPasswordEnc: rootPassword ? encryptSecret(rootPassword) : null, hostnameFqdn, maxAccounts },
  });
  revalidatePath("/admin/hosting");
  return { ok: true };
}

export async function adminToggleHostingNode(id: string): Promise<void> {
  await requireArea("fleet");
  const n = await db.hostingNode.findUnique({ where: { id } });
  if (n) await db.hostingNode.update({ where: { id }, data: { enabled: !n.enabled } });
  revalidatePath("/admin/hosting");
}

/**
 * Queue a node for hardening: the worker sweep (hostingNodeHardenSweep) runs
 * scripts/onboard-hosting-node.sh on the box over the platform's own SSH (the
 * node's stored encrypted root password), so the owner can apply the WAF +
 * ClamAV + hardening steps without knowing the node's root password. The onboard
 * script is idempotent and nginx -t-guarded. Fleet-guarded, same as the toggle.
 * Refuses while a run is already QUEUED/RUNNING so a double-click can't stack runs.
 */
export async function adminHardenHostingNode(id: string): Promise<{ ok?: boolean; error?: string }> {
  await requireArea("fleet");
  const n = await db.hostingNode.findUnique({ where: { id }, select: { hardenStatus: true } });
  if (!n) return { error: "Node not found." };
  if (n.hardenStatus === "QUEUED" || n.hardenStatus === "RUNNING") {
    return { error: "Hardening is already in progress for this node." };
  }
  await db.hostingNode.update({ where: { id }, data: { hardenStatus: "QUEUED", hardenLog: null } });
  revalidatePath("/admin/hosting");
  return { ok: true };
}

// ---------- Admin account lifecycle -----------------------------------------
// Suspend / unsuspend / terminate a customer's hosting account. The DB status
// flips immediately (so the operator sees it), and a HostingTask is queued for
// the provisioner to enact the OS-level change (inert until ENABLE_SHARED_HOSTING).

export type AdminHostingAccountView = {
  id: string;
  username: string;
  primaryDomain: string;
  userEmail: string;
  planName: string;
  nodeLabel: string;
  status: string;
  diskQuotaMB: number;
  sslActive: boolean;
  createdAt: string;
};

export async function adminListHostingAccounts(): Promise<AdminHostingAccountView[]> {
  await requireArea("fleet");
  const rows = await db.hostingAccount.findMany({
    orderBy: { createdAt: "desc" },
    include: {
      user: { select: { email: true } },
      plan: { select: { name: true } },
      node: { select: { publicIp: true, hostnameFqdn: true } },
    },
  });
  return rows.map((a) => ({
    id: a.id,
    username: a.username,
    primaryDomain: a.primaryDomain,
    userEmail: a.user?.email ?? "—",
    planName: a.plan?.name ?? "—",
    nodeLabel: a.node?.hostnameFqdn || a.node?.publicIp || "—",
    status: a.status,
    diskQuotaMB: a.diskQuotaMB,
    sslActive: a.sslActive,
    createdAt: a.createdAt.toISOString(),
  }));
}

/** Queue a lifecycle task for the provisioner (idempotent enough — dupes are cheap). */
async function queueLifecycleTask(accountId: string, kind: "SUSPEND" | "UNSUSPEND" | "TERMINATE"): Promise<void> {
  await db.hostingTask.create({ data: { accountId, kind, status: "PENDING" } });
}

export async function adminSuspendHostingAccount(id: string): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("fleet");
  const a = await db.hostingAccount.findUnique({ where: { id }, select: { status: true } });
  if (!a) return { error: "Account not found." };
  if (!["ACTIVE", "PROVISIONING", "FAILED"].includes(a.status)) return { error: `Can't suspend an account that is ${a.status.toLowerCase()}.` };
  await db.hostingAccount.update({ where: { id }, data: { status: "SUSPENDED" } });
  await queueLifecycleTask(id, "SUSPEND");
  revalidatePath("/admin/hosting");
  return { ok: true };
}

export async function adminUnsuspendHostingAccount(id: string): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("fleet");
  const a = await db.hostingAccount.findUnique({ where: { id }, select: { status: true } });
  if (!a) return { error: "Account not found." };
  if (a.status !== "SUSPENDED") return { error: "Only a suspended account can be reactivated." };
  await db.hostingAccount.update({ where: { id }, data: { status: "ACTIVE" } });
  await queueLifecycleTask(id, "UNSUSPEND");
  revalidatePath("/admin/hosting");
  return { ok: true };
}

export async function adminTerminateHostingAccount(id: string): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("fleet");
  const a = await db.hostingAccount.findUnique({ where: { id }, select: { status: true } });
  if (!a) return { error: "Account not found." };
  if (a.status === "DELETING") return { error: "Already terminating." };
  await db.hostingAccount.update({ where: { id }, data: { status: "DELETING" } });
  await queueLifecycleTask(id, "TERMINATE");
  revalidatePath("/admin/hosting");
  return { ok: true };
}

/**
 * Self-serve cancel: the OWNER closes their own hosting account. Mirrors
 * `adminTerminateHostingAccount` (set DELETING → queue a TERMINATE lifecycle task
 * for the provisioner, which removes files, databases and sites) but gated to the
 * account owner instead of the fleet admin area. Ownership is checked the SAME way
 * every other customer hosting action in this file does (`a.userId !== user.id`,
 * with ADMIN allowed through). Irreversible; the UI requires a strong typed
 * confirmation before calling this. Refuses cleanly if the caller doesn't own the
 * account or it is already terminating.
 */
export async function cancelHostingAccount(accountId: string): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  // Spend/destroy path: an impersonating admin must not close a customer's account
  // while acting as them (same discipline as the order paths above).
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, status: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status === "DELETING") return { error: "This account is already being cancelled." };
  await db.hostingAccount.update({ where: { id: accountId }, data: { status: "DELETING" } });
  await queueLifecycleTask(accountId, "TERMINATE");
  await db.auditLog.create({
    data: { userId: user.id, action: "hosting.cancel", detail: `self-serve cancel · ${accountId}` },
  }).catch(() => {});
  revalidatePath("/dashboard/hosting");
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

