481	// ---- Wildcard cert for free subdomains (DNS-01, one cert per node) ----------
482	
483	/**
484	 * A Cloudflare DNS API token safe to write into the certbot credentials file:
485	 * the exact charset Cloudflare mints (alnum plus `_`/`-`), length-bounded, and —
486	 * crucially — free of any shell/ini metacharacter. It lands in a file, not a
487	 * command, but an unvalidated secret never goes near a shell here, so we reject
488	 * anything outside this alphabet.
489	 */
490	const CF_TOKEN_RE = /^[A-Za-z0-9_-]{20,120}$/;
491	/** apt install of certbot + the DNS plugin, and a DNS-01 issuance (30s propagation
492	 *  wait built in), each run minutes — well past a single node STEP. */
493	const WILDCARD_STEP_MS = 5 * 60_000;
494	
495	/**
496	 * Mint (or renew) the ONE wildcard cert `*.<base>` (+ the apex `<base>`) via
497	 * certbot DNS-01 against Cloudflare on this node, so every free-subdomain site
498	 * gets INSTANT trusted HTTPS off a single Let's Encrypt lineage instead of a
499	 * per-subdomain HTTP-01 cert (slow AND capped at ~50 certs/week per registered
500	 * domain — a hard wall once signups scale).
501	 *
502	 * Fully opt-in + inert: does nothing unless hostingWildcardEnabled() (the
503	 * HOSTING_WILDCARD_SSL flag) AND a Cloudflare token is present AND shared hosting
504	 * is enabled AND not sandbox. Idempotent: `--keep-until-expiring` makes a run a
505	 * no-op until the cert is near expiry (so the ~daily cadence never churns LE), and
506	 * the credentials file is rewritten `600 root:root` each time. The token is
507	 * validated to a strict charset BEFORE it is ever written.
508	 */
509	export async function ensureWildcardCert(conn: Client): Promise<void> {
510	  if (SANDBOX || !ENABLED || !hostingWildcardEnabled()) return;
511	  const token = String(process.env.CLOUDFLARE_DNS_API_TOKEN ?? "").trim();
512	  if (!token) return; // no credential → silently skip (still inert)
513	  if (!CF_TOKEN_RE.test(token)) throw new Error("refusing unsafe CLOUDFLARE_DNS_API_TOKEN (charset)");
514	  const base = HOSTING_SUBDOMAIN_BASE;
515	  if (!isValidHostingDomain(base)) throw new Error(`refusing unsafe wildcard base ${base}`);
516	
517	  // 1. certbot + the Cloudflare DNS plugin — only installs when absent (idempotent).
518	  const inst = await exec(
519	    conn,
520	    `if ! command -v certbot >/dev/null 2>&1 || ! python3 -c 'import certbot_dns_cloudflare' >/dev/null 2>&1; then ` +
521	      `DEBIAN_FRONTEND=noninteractive apt-get update -qq && ` +
522	      `DEBIAN_FRONTEND=noninteractive apt-get install -y certbot python3-certbot-dns-cloudflare; fi`,
523	    WILDCARD_STEP_MS,
524	  );
525	  if (inst.code !== 0) throw new Error(`wildcard: certbot install failed: ${inst.out.slice(0, 200)}`);
526	
527	  // 2. Credentials file — root-only (600), written with umask so it is never even
528	  //    briefly world-readable. Token is validated to [A-Za-z0-9_-] so it is safe
529	  //    inside the single-quoted printf arg.
530	  const cred = await exec(
531	    conn,
532	    `mkdir -p /etc/letsencrypt && ( umask 077 && printf 'dns_cloudflare_api_token = %s\\n' '${token}' > /etc/letsencrypt/cloudflare.ini ) && ` +
533	      `chown root:root /etc/letsencrypt/cloudflare.ini && chmod 600 /etc/letsencrypt/cloudflare.ini`,
534	  );
535	  if (cred.code !== 0) throw new Error(`wildcard: writing cloudflare.ini failed: ${cred.out.slice(0, 200)}`);
536	
537	  // 3. Issue/renew the wildcard. --cert-name <base> pins the lineage so the live
538	  //    dir path (wildcardCertLiveDir) is stable; --keep-until-expiring no-ops until
539	  //    near expiry. `base` is a validated hostname ([a-z0-9.-]) so it is shell-inert.
540	  const issue = await exec(
541	    conn,
542	    `certbot certonly --dns-cloudflare --dns-cloudflare-credentials /etc/letsencrypt/cloudflare.ini ` +
543	      `--dns-cloudflare-propagation-seconds 30 -d '*.${base}' -d '${base}' --cert-name ${base} ` +
544	      `--non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`,
545	    WILDCARD_STEP_MS,
546	  );
547	  const liveDir = wildcardCertLiveDir();
548	  if (!(await fileExistsOnNode(conn, `${liveDir}/fullchain.pem`))) {
549	    throw new Error(`wildcard cert not present after issuance: ${issue.out.slice(-240)}`);
550	  }
551	  console.log(`[hosting] wildcard cert ready for *.${base} on node`);
552	}
